import base64, hashlib, hmac, json, time
# 1) Verify an HS256 JWT-style token (real OIDC uses RS256 + the IdP's JWKS; the checks are the same).
SECRET = b"demo-only-secret"
b64 = lambda b: base64.urlsafe_b64encode(b).rstrip(b"=")
def sign(claims):
    h, p = b64(json.dumps({"alg": "HS256"}).encode()), b64(json.dumps(claims).encode())
    return b".".join([h, p, b64(hmac.new(SECRET, h + b"." + p, hashlib.sha256).digest())]).decode()
def verify(token, aud, iss):
    h, p, s = token.encode().split(b".")
    if not hmac.compare_digest(b64(hmac.new(SECRET, h + b"." + p, hashlib.sha256).digest()), s): raise PermissionError("bad signature")
    c = json.loads(base64.urlsafe_b64decode(p + b"=" * (-len(p) % 4)))
    if c["aud"] != aud or c["iss"] != iss or c["exp"] < time.time(): raise PermissionError("bad aud/iss/exp")
    return c
# 2) RBAC from IdP groups + an ABAC rule, enforced in the tool, not the prompt.
ROLE_OF_GROUP = {"HR-Partners": "hr_partner", "Employees": "employee"}
RECORDS = [{"id": 1, "region": "EU", "salary": 81000}, {"id": 2, "region": "US", "salary": 95000}]
def search_salaries(token):
    u = verify(token, aud="hr-assistant", iss="https://idp.example.com")
    roles = {ROLE_OF_GROUP[g] for g in u["groups"] if g in ROLE_OF_GROUP}
    return [r for r in RECORDS if "hr_partner" in roles and r["region"] == u["region"]]
t_eu = sign({"sub": "ana", "groups": ["HR-Partners"], "region": "EU", "aud": "hr-assistant", "iss": "https://idp.example.com", "exp": time.time() + 300})
t_emp = sign({"sub": "bo", "groups": ["Employees"], "region": "US", "aud": "hr-assistant", "iss": "https://idp.example.com", "exp": time.time() + 300})
print("ana:", search_salaries(t_eu)); print("bo:", search_salaries(t_emp))

import hashlib, queue, threading, random
# Embedding cache by content hash + a worker pool with retries and a dead-letter queue.
CACHE, DLQ, calls = {}, [], {"n": 0}
lock = threading.Lock()
def embed_api(text):                       # stub for a paid, rate-limited API that sometimes fails
    with lock: calls["n"] += 1
    if random.random() < 0.1: raise TimeoutError("transient")
    return [len(text) % 7, len(text) % 11]
def embed_cached(text, model="emb-v3"):
    key = hashlib.sha256(f"{model}|{text}".encode()).hexdigest()
    with lock:
        if key in CACHE: return CACHE[key]
    vec = embed_api(text)
    with lock: CACHE[key] = vec
    return vec
jobs = queue.Queue()
def worker():
    while True:
        item = jobs.get()
        if item is None: break
        text, attempt = item
        try: embed_cached(text)
        except TimeoutError as e:
            if attempt < 3: jobs.put((text, attempt + 1))    # retry (a real system adds backoff)
            else: DLQ.append((text, str(e)))
        finally: jobs.task_done()
random.seed(1)
chunks = [f"chunk {i % 300}" for i in range(1000)]          # lots of repeats
for c in chunks: jobs.put((c, 0))
ts = [threading.Thread(target=worker) for _ in range(8)]
for t in ts: t.start()
jobs.join()
for _ in ts: jobs.put(None)
for t in ts: t.join()
print(f"{len(chunks)} chunks, {len(CACHE)} unique embedded, {calls['n']} API calls, DLQ={len(DLQ)}")

import json
# Dated API versions with per-account pinning and server-side translation (Stripe-style), plus problem-details errors.
VERSIONS = ["2025-06-01", "2026-10-01"]
ACCOUNT_VERSION = {"acct_old": "2025-06-01", "acct_new": "2026-10-01"}
PRIORITY_TO_LEVEL = {"low": 1, "normal": 3, "high": 5}
def internal_ticket(tid):            # latest internal representation
    return {"id": tid, "title": "VPN down", "priority_level": 5}
DOWNGRADES = {                       # one function per version change, applied newest -> oldest
    "2026-10-01": lambda t: {**{k: v for k, v in t.items() if k != "priority_level"},
                             "priority": {v: k for k, v in PRIORITY_TO_LEVEL.items()}[t["priority_level"]]},
}
def render(ticket, version):
    for v in reversed(VERSIONS):
        if v <= version: break
        ticket = DOWNGRADES[v](ticket)
    return ticket
def get_ticket(account, tid, header_version=None):
    version = header_version or ACCOUNT_VERSION.get(account, VERSIONS[-1])
    if version not in VERSIONS:
        return 400, {"type": "https://api.example.com/problems/unknown-version", "title": "Unknown API version",
                     "status": 400, "detail": f"Use one of {VERSIONS}"}
    return 200, render(internal_ticket(tid), version)
print(get_ticket("acct_old", "T-1"))      # pinned: gets 'priority': 'high'
print(get_ticket("acct_new", "T-1"))      # latest: gets 'priority_level': 5
print(json.dumps(get_ticket("acct_old", "T-1", "2024-01-01")[1]))

import random, time
# Retries with full jitter (retryable errors only) + idempotency keys + a token-bucket limiter + a tiny circuit breaker.
class Retryable(Exception): pass
class Fatal(Exception): pass
def call_with_retries(fn, *, attempts=5, base=0.02, cap=0.5, deadline_s=2.0, rng=random.Random(7)):
    start = time.monotonic()
    for i in range(attempts):
        try: return fn()
        except Fatal: raise                                    # never retry e.g. 400s
        except Retryable:
            sleep = rng.uniform(0, min(cap, base * 2 ** i))   # full jitter
            if i == attempts - 1 or time.monotonic() - start + sleep > deadline_s: raise
            time.sleep(sleep)
class TokenBucket:
    def __init__(self, rate, capacity): self.rate, self.cap, self.tokens, self.t = rate, capacity, capacity, time.monotonic()
    def allow(self):
        now = time.monotonic(); self.tokens = min(self.cap, self.tokens + (now - self.t) * self.rate); self.t = now
        if self.tokens >= 1: self.tokens -= 1; return True
        return False
class Breaker:
    def __init__(self, threshold=3, cooldown=0.2): self.fail, self.th, self.cd, self.opened = 0, threshold, cooldown, None
    def __call__(self, fn):
        if self.opened and time.monotonic() - self.opened < self.cd: raise Retryable("circuit open")
        try: r = fn(); self.fail, self.opened = 0, None; return r
        except Retryable: self.fail += 1; self.opened = time.monotonic() if self.fail >= self.th else None; raise
IDEMP = {}
def create_refund(key, amount):                                # server side
    if key in IDEMP: return IDEMP[key]
    IDEMP[key] = {"refund_id": f"re_{len(IDEMP) + 1}", "amount": amount}; return IDEMP[key]
flaky = iter([Retryable("503"), Retryable("timeout"), None])
def attempt():
    e = next(flaky)
    if e: raise e
    return create_refund("idem-123", 20)
print(call_with_retries(attempt)); print(create_refund("idem-123", 20))   # same refund, not a second one
tb = TokenBucket(rate=5, capacity=10); print("burst allowed:", sum(tb.allow() for _ in range(25)), "of 25")
br = Breaker()
def down(): raise Retryable("503")
for _ in range(4):
    try: br(down)
    except Retryable as e: last = str(e)
print("breaker:", last)
